struct Table {
	const char* name;  // the skills.txt column
	uint64_t rva;
	int slots;
	int firstFree;
};

struct SlotFunction {
	const Table& table;
	int slot;  // the skills.txt value
	const void* function;
	const char* name;
};

// Socketed gems and runes apply their gems.txt mods once (#450).
//
// Our merged misc.txt gives every gem and rune compactsave=0 (PD2's stacks need it). D2R then keeps the filler's own
// stat list as well as applying gems.txt, so the mods count twice on insertion and a third time after a reload.
// A socketed filler is always one item and never comes out, so after its mods are applied it gets the item flag
// compact (0x200000): the save and the item packet then write it without stats, as vanilla's compactsave=1 does.
// The SDK has no service for item flags or this function, hence the native hook (pd2_engine.h).

const D2RL::Mutations::BytePatchRequest patch{.structSize = D2RL::Mutations::BytePatchRequestSize,
                                              .rva = d2r::rva::ItemsJsonKey,
                                              .expected = d2r::rva::ItemsJsonKeyD2R,
                                              .expectedSize = sizeof(d2r::rva::ItemsJsonKeyD2R),
                                              .bytes = d2r::rva::ItemsJsonKeyFull,
                                              .size = sizeof(d2r::rva::ItemsJsonKeyFull)};

const D2RL::Mutations::BytePatchRequest spawn{.structSize = D2RL::Mutations::BytePatchRequestSize,
                                              .rva = d2r::rva::SpawnCheatKey,
                                              .expected = d2r::rva::SpawnCheatKeyD2R,
                                              .expectedSize = sizeof(d2r::rva::SpawnCheatKeyD2R),
                                              .bytes = d2r::rva::SpawnCheatKeyFull,
                                              .size = sizeof(d2r::rva::SpawnCheatKeyFull)};

// The quantity display, by a native hook (AGENTS.md: SDK first). Why a hook: D2RLoader 1.3.1's WidgetService has no
// getWidgetScreenRect (64 bytes; core-ui logged `widget 1 (size 64, needs 208)`) and its OverlayService draws nothing,
// so the SDK cannot place or draw the number (#359). The D2RLoader dev says the screen-rect call is coming; then this
// file can go back to the SDK version (WidgetService + InventoryService + OverlayService, commit e8da7c5 of PR #402).
// Everything native sits in this file.
//
// The hook replaces D2R's item draw 0x2a72d0 (widget, item), which every item widget calls once per item: it does
// what D2R does (picture rect from the grid's vtable, then the picture), then for a stackable item draws its quantity
// stat (70) with D2R's text draw 0x902e20, in the picture rect aligned right and bottom. Drawn inside the grid's own
// draw, so tooltips and the cursor item cover it, as they cover the picture.
//
// PD2 (its D2GL renderer, config 6, which `HOTKEY_ItemQuantity` toggles) draws the quantity of every grid item that has
// one, in white over a 60%-black box, at the bottom left. Here: bottom right (#359 asks for it), white with D2R's drop
// shadow instead of the box (docs/deviations.md).

// D2WinFont, 0xa4 bytes: the defaults its builder 0x86d1b0 writes, then the fields set here (offsets from the style
// reflection at 0x8bd030: pointSize +4, fontColor +8 (r, g, b, a ints), alignment +0x28 (h, v; left 0, center 1,
// right 2, from 0x8ba810), dropShadow offset +0x70 and colour +0x78). Last int: the font preset, 0xe for none.

// core-ui: PD2's client-side engine features no companion covers, for PD2 Resurrected. Client-only (not Shared: a UI
// change must never force host and client to match) and NativeHooks; a mod-scoped plugin in <game>\mods\<mod>\d2rloader\plugins
// (ADR 0004, #1180). On a game image other than the one in rvas_*.h it loads, logs the stamp and leaves every part off.
//
// Parts, by their word for the log, the status command and core-ui-off.txt (<game>\mods\<mod>\d2rloader\config\core-ui-off.txt):
//   pictures  HD pictures of PD2's 4-character item codes (#310, #298), and `cheat spawn` of them (#323)
//   split     PD2's stack split: Ctrl+left-click with a stack held puts one item down (#316)
//   quantity  PD2's Show Item Quantity: each stack in an open grid shows its quantity on its picture (#359)
//   palette   legacy graphics: a level entered without a load screen draws in its own palette (#296)

// The split, all through the PluginSDK (no D2R hook): the SDK has no mouse event and no event for an item put down
// from the cursor (ItemInteractionService skips cursor paths), so a UI-thread watch sees the cursor each update. When a
// stack of N > 1 leaves it with Ctrl down, a game-thread job finds that same stack, whole, in a stored grid and
// splitStack takes N-1 of it back to the cursor. D2R itself chose the cell and the panel (inventory, cube, stash), and
// splitStack moves quantity between the stack and a new cursor stack in one step, so nothing is lost or made twice.
// PD2 instead sends its own packet 0x22 and makes a new 1-quantity item at the cell (docs/research/items/stack-split.md);
// the result is the same, but the one item left down here is the original and the cursor stack is the new one.
// In core-ui (client-only, ADR 0004) though it changes items: the result is what a put-down and a pick-up would give.
//
// shortcut: a TCP/IP client has no game thread (runOnGameThread is Unavailable), so it gets no split; upgrade with a
// plugin message to the host if online play needs it.
// A Ctrl+click on a stored stack of the same item (#362): D2R merges the whole held stack into it, so while a stack is
// held the watch notes the stored stacks with its code, and the job splits N-1 back off the one that rose by N.
// shortcut: a merge that stops at the stack cap leaves the rest on the cursor, and that is kept as D2R does it (PD2
// would add one); upgrade if players miss it.
// Pad: Controller QoL's item modifier (LB by default) held with A is the Ctrl of a pad (controller_split.cpp).
